import { MeshBasicNodeMaterial, MeshStandardNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, vec2, color, mix, smoothstep, float, uniform, positionLocal, sin } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    Group, Mesh, PlaneGeometry, CylinderGeometry, RingGeometry, Shape,
    ExtrudeGeometry, DirectionalLight,
  } = ctx.THREE;

  const COLORS = (config.intent && config.intent.visualSpec && config.intent.visualSpec.colors) || {};
  const ACCENT = COLORS.accent || '#ff2a38';
  const PAPER = COLORS.paper || '#e8ecf2';
  const GRAD_TOP = '#191921';
  const GRAD_BOT = '#121218';
  const BORDER = '#26262f';

  const root = new Group();
  root.name = 'feature-triptych';

  const disposables = [];
  const timelines = [];
  const primHandles = [];

  // ---------------------------------------------------------------
  // Backdrop stage plane (7x6 @ z=-2.5) — gradient + radial light lift
  // so the field reads as a lit stage, never a flat fill.
  // ---------------------------------------------------------------
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  {
    const grad = mix(color('#1e1e28'), color('#0e0e13'), uv().y.oneMinus());
    const d = uv().distance(vec2(0.5, 0.56));
    const lift = smoothstep(float(0.78), float(0.12), d).mul(0.55).add(0.72);
    // faint machined horizontal banding, barely visible, kills the void read
    const band = sin(uv().y.mul(240.0)).mul(0.012).add(1.0);
    backdropMat.colorNode = grad.mul(lift).mul(band);
  }
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, -0.25, -2.5);
  root.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // Node-local lights: upper-left fill (so lifted cards gain a bright top
  // bevel) + lower-right accent rim. Scene supplies ambient 0.6 / key 1.2.
  const fill = new DirectionalLight('#e8ecf2', 0.6);
  fill.position.set(-2.2, 2.6, 3.0);
  root.add(fill);

  const rim = new DirectionalLight(ACCENT, 0.7);
  rim.position.set(2.5, -1.8, 2.5);
  root.add(rim);

  // ---------------------------------------------------------------
  // Text items (bridge idiom)
  // ---------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const glyphs = items.filter((i) => i.role === 'icon-glyph').map((i) => i.text);
  const titles = items.filter((i) => i.role === 'card-title').map((i) => i.text);
  const bodies = items.filter((i) => i.role === 'body').map((i) => i.text);

  // ---------------------------------------------------------------
  // Card geometry
  // ---------------------------------------------------------------
  const CARD_W = 1.5;
  const CARD_H = 1.9;
  const GAP = 0.25;
  const RADIUS = 0.06;

  function roundedRectShape(w, h, r) {
    const s = new Shape();
    const x = -w / 2, y = -h / 2;
    s.moveTo(x + r, y);
    s.lineTo(x + w - r, y);
    s.quadraticCurveTo(x + w, y, x + w, y + r);
    s.lineTo(x + w, y + h - r);
    s.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    s.lineTo(x + r, y + h);
    s.quadraticCurveTo(x, y + h, x, y + h - r);
    s.lineTo(x, y + r);
    s.quadraticCurveTo(x, y, x + r, y);
    return s;
  }

  const cardShape = roundedRectShape(CARD_W, CARD_H, RADIUS);
  const cardGeo = new ExtrudeGeometry(cardShape, {
    depth: 0.04,
    bevelEnabled: true,
    bevelThickness: 0.012,
    bevelSize: 0.012,
    bevelSegments: 3,
    curveSegments: 12,
  });
  disposables.push(cardGeo);

  const borderShape = roundedRectShape(CARD_W + 0.012, CARD_H + 0.012, RADIUS + 0.006);
  const borderGeo = new ExtrudeGeometry(borderShape, { depth: 0.02, bevelEnabled: false, curveSegments: 12 });
  disposables.push(borderGeo);

  const discGeo = new CylinderGeometry(0.2, 0.2, 0.05, 64);
  discGeo.rotateX(Math.PI / 2);
  disposables.push(discGeo);

  const ringGeo = new RingGeometry(0.182, 0.196, 64);
  disposables.push(ringGeo);

  const shadowGeo = new PlaneGeometry(1.8, 0.5);
  disposables.push(shadowGeo);

  // Card face shading — engineered vertical ramp + hairline top light +
  // soft diagonal sweep from the upper-left key. positionLocal is reliable
  // on ExtrudeGeometry where UVs are not.
  const py = positionLocal.y.div(CARD_H).add(0.5).clamp(0, 1); // 0 bottom -> 1 top
  const baseRamp = mix(color(GRAD_BOT), color(GRAD_TOP), py);
  const topEdge = smoothstep(float(0.955), float(1.0), py);
  const sweep = smoothstep(float(-1.4), float(1.4), positionLocal.y.sub(positionLocal.x.mul(0.7))).mul(0.10);
  const cardFaceColor = mix(baseRamp, color('#2e2e3a'), topEdge.mul(0.7).add(sweep));

  // Machined disc shading — concentric brushed rings + recessed glyph seat.
  const rr = positionLocal.xy.length();
  const rings = sin(rr.mul(420.0)).mul(0.5).add(0.5);
  const seat = smoothstep(float(0.125), float(0.145), rr); // 0 inside recess, 1 outside
  const brushed = mix(color('#3c3c46'), color('#5a5a66'), rings.mul(0.35).add(rr.mul(1.4)).clamp(0, 1));
  const discColor = mix(color('#17171d'), brushed, seat);
  const discRough = float(0.55).sub(rings.mul(0.08));

  // Vertical rhythm on the 0.25 baseline grid (padding 0.375):
  const DISC_Y = 0.375;   // 0.4 disc, top edge at 0.575
  const TITLE_Y = -0.14;  // 0.25 gap below disc bottom (0.175)
  const TICK_Y = -0.26;
  const BODY_TOP = -0.38; // 0.125+ gap below title, wraps to <=3 lines
  const LINE_H = 0.105;

  const TITLE_SCALE = 0.0058;
  const BODY_SCALE = 0.0055;
  const GLYPH_SCALE = 0.0055;

  // Hard word-wrap: body copy is broken into explicit lines so it can
  // never escape the card column or collide with a neighbor.
  function wrapText(text, maxChars) {
    const words = String(text).split(' ');
    const lines = [];
    let cur = '';
    for (const w of words) {
      const next = cur ? cur + ' ' + w : w;
      if (next.length > maxChars && cur) { lines.push(cur); cur = w; }
      else cur = next;
    }
    if (cur) lines.push(cur);
    return lines;
  }

  const cards = [];
  const xs = [-(CARD_W + GAP), 0, CARD_W + GAP];

  for (let i = 0; i < 3; i++) {
    const card = new Group();
    card.name = 'feature-card-' + i;
    card.position.set(xs[i], 0, 0);

    // hairline border frame
    const borderMat = new MeshBasicNodeMaterial({ transparent: true });
    borderMat.colorNode = color(BORDER);
    const border = new Mesh(borderGeo, borderMat);
    border.position.z = -0.015;
    card.add(border);
    disposables.push(borderMat);

    // card face — PBR within proven ranges, lit ramp
    const faceMat = new MeshPhysicalNodeMaterial({
      roughness: 0.55,
      metalness: 0.3,
      clearcoat: 0.15,
      clearcoatRoughness: 0.5,
      transparent: true,
    });
    faceMat.colorNode = cardFaceColor;
    const face = new Mesh(cardGeo, faceMat);
    card.add(face);
    disposables.push(faceMat);

    // machined icon seat — brushed concentric rings, recessed center
    const discMat = new MeshPhysicalNodeMaterial({
      metalness: 0.5,
      clearcoat: 0.2,
      clearcoatRoughness: 0.35,
      transparent: true,
    });
    discMat.colorNode = discColor;
    discMat.roughnessNode = discRough;
    const disc = new Mesh(discGeo, discMat);
    disc.position.set(0, DISC_Y, 0.09);
    card.add(disc);
    disposables.push(discMat);

    // crisp machined accent ring at the disc rim (emissive, hover-driven)
    const ringIntensity = uniform(1.6);
    const ringMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
    ringMat.colorNode = color(ACCENT).mul(ringIntensity.mul(0.62));
    const ring = new Mesh(ringGeo, ringMat);
    ring.position.set(0, DISC_Y, 0.122);
    card.add(ring);
    disposables.push(ringMat);

    // glyph — accent mono numeral seated in the recess
    if (glyphs[i]) {
      const glyph = ctx.fontAtlas.createText(String(glyphs[i]), {
        fontSize: 20,
        color: ACCENT,
        align: 'center',
        letterSpacingPx: 1,
      });
      glyph.scale.setScalar(GLYPH_SCALE);
      glyph.position.set(0, DISC_Y, 0.125);
      card.add(glyph);
    }

    // title — serif display tier, single centered line inside the column
    if (titles[i]) {
      const title = ctx.fontAtlas.createText(String(titles[i]), {
        fontSize: 20,
        color: PAPER,
        align: 'center',
        maxWidthPx: 216,
      });
      title.scale.setScalar(TITLE_SCALE);
      title.position.set(0, TITLE_Y, 0.09);
      card.add(title);
    }

    // accent tick between title and body — anchored inside the card
    const tickGeo = new PlaneGeometry(0.28, 0.01);
    const tickMat = new MeshBasicNodeMaterial({ transparent: true });
    tickMat.colorNode = color(ACCENT);
    const tick = new Mesh(tickGeo, tickMat);
    tick.position.set(0, TICK_Y, 0.09);
    card.add(tick);
    disposables.push(tickGeo, tickMat);

    // body — hard-wrapped mono lines, one text object per line
    if (bodies[i]) {
      const lines = wrapText(bodies[i], 24);
      lines.forEach((line, li) => {
        const bodyLine = ctx.fontAtlas.createText(line, {
          fontSize: 13,
          color: '#c7cdd8',
          align: 'center',
          maxWidthPx: 228,
        });
        bodyLine.scale.setScalar(BODY_SCALE);
        bodyLine.position.set(0, BODY_TOP - li * LINE_H, 0.09);
        card.add(bodyLine);
      });
    }

    // contact shadow — widens + softens on lift
    const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
    shadowMat.colorNode = color('#000000');
    shadowMat.opacityNode = smoothstep(float(0.5), float(0.08), uv().distance(vec2(0.5))).mul(0.5);
    const shadow = new Mesh(shadowGeo, shadowMat);
    shadow.position.set(0, -1.05, -0.1);
    card.add(shadow);
    disposables.push(shadowMat);

    root.add(card);
    cards.push({ card, shadow, ringIntensity, hoverTl: null });
  }

  // grounding shelf line under the row — neutral, anchored to the shadows
  const shelfGeo = new PlaneGeometry(5.2, 0.008);
  const shelfMat = new MeshBasicNodeMaterial({ transparent: true });
  shelfMat.colorNode = color(BORDER);
  shelfMat.opacityNode = float(0.55);
  const shelf = new Mesh(shelfGeo, shelfMat);
  shelf.position.set(0, -1.12, -0.05);
  root.add(shelf);
  disposables.push(shelfGeo, shelfMat);

  // ---------------------------------------------------------------
  // Mount: stagger-cards fade-up (500ms power2.out, 80ms stagger)
  // ---------------------------------------------------------------
  const cardMats = cards.map(({ card }) => {
    const mats = [];
    card.traverse((o) => {
      if (o.material) {
        o.material.transparent = true;
        mats.push(o.material);
      }
    });
    return mats;
  });

  const mountTl = gsap.timeline();
  cards.forEach(({ card }, i) => {
    const mats = cardMats[i];
    mats.forEach((m) => { m.opacity = 0; });
    card.position.y = -0.2;
    const state = { t: 0 };
    mountTl.to(state, {
      t: 1,
      duration: 0.5,
      ease: 'power2.out',
      onUpdate: () => {
        card.position.y = -0.2 * (1 - state.t);
        for (const m of mats) m.opacity = state.t;
      },
    }, i * 0.08);
  });
  mountTl.fromTo(root.scale, { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0.55);
  timelines.push(mountTl);

  // ---------------------------------------------------------------
  // Hover lift
  // ---------------------------------------------------------------
  function liftCard(i, lifted) {
    const entry = cards[i];
    if (!entry) return;
    if (entry.hoverTl) entry.hoverTl.kill();
    const tl = gsap.timeline();
    tl.to(entry.card.position, {
      y: lifted ? 0.06 : 0,
      z: lifted ? 0.12 : 0,
      duration: 0.18,
      ease: 'power2.out',
    }, 0);
    tl.to(entry.shadow.scale, {
      x: lifted ? 1.18 : 1,
      y: lifted ? 1.12 : 1,
      duration: 0.18,
      ease: 'power2.out',
    }, 0);
    tl.to(entry.shadow.position, {
      y: lifted ? -1.09 : -1.05,
      duration: 0.18,
      ease: 'power2.out',
    }, 0);
    tl.to(entry.ringIntensity, {
      value: lifted ? 2.2 : 1.6,
      duration: 0.18,
      ease: 'power2.out',
    }, 0);
    entry.hoverTl = tl;
    timelines.push(tl);
  }

  function findCardIndex(obj) {
    let o = obj;
    while (o) {
      const idx = cards.findIndex((c) => c.card === o);
      if (idx !== -1) return idx;
      o = o.parent;
    }
    return -1;
  }

  root.userData.handlers = {
    pointerenter: (e) => {
      const idx = e && e.object ? findCardIndex(e.object) : -1;
      if (idx !== -1) liftCard(idx, true);
    },
    pointerleave: () => {
      for (let i = 0; i < cards.length; i++) liftCard(i, false);
    },
    pointermove: (e) => {
      const idx = e && e.object ? findCardIndex(e.object) : -1;
      for (let i = 0; i < cards.length; i++) liftCard(i, i === idx);
    },
  };

  cards.forEach((entry, i) => {
    entry.card.userData.handlers = {
      pointerenter: () => liftCard(i, true),
      pointerleave: () => liftCard(i, false),
    };
  });

  // ---------------------------------------------------------------
  // Cinematic primitives from config (none shipped, applied if present)
  // ---------------------------------------------------------------
  for (const primitive of (config.cinematicPrimitives || [])) {
    if (ctx.primitives[primitive.name]) {
      primHandles.push(ctx.primitives[primitive.name](root, primitive.params));
    }
  }

  // ---------------------------------------------------------------
  // Cleanup
  // ---------------------------------------------------------------
  root.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    for (const entry of cards) {
      if (entry.hoverTl) entry.hoverTl.kill();
    }
    for (const h of primHandles) {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    }
    for (const d of disposables) {
      if (d && typeof d.dispose === 'function') d.dispose();
    }
    root.traverse((o) => {
      if (o.geometry && typeof o.geometry.dispose === 'function') o.geometry.dispose();
      if (o.material && typeof o.material.dispose === 'function') o.material.dispose();
    });
    if (root.parent) root.parent.remove(root);
  };

  return root;
}
